{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "Subject to appropriation, the state department of education would give each local education agency (LEA) enough money to employ one full-time licensed professional school counselor at each high school that enrolls at least 600 students in grades 10 through 12.",
      "rationale": "Conveys the allocation requirement, appropriation condition, counselor qualifications, and school enrollment threshold."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "If an LEA already has part-time licensed counselors at a qualifying high school, it may use the money to make a part-time counselor full-time, and doing so meets the hiring requirement.",
      "rationale": "Covers the permitted conversion and its satisfaction of the employment requirement; qualifying schools are defined earlier."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "If an LEA already employs one full-time licensed counselor for every 250 students in the LEA, it may use the money to cover the cost of the counselors needed to meet that ratio.",
      "rationale": "Conveys the LEA-wide staffing ratio and permission to use funding for existing costs of meeting that ratio."
    },
    {
      "proposition_id": "P4",
      "status": "full",
      "summary_quote": "Each LEA would then have to employ one full-time licensed professional school counselor at each high school for which it receives this funding.\n\nThe bill allows some flexibility. If an LEA already has part-time licensed counselors at a qualifying high school, it may use the money to make a part-time counselor full-time, and doing so meets the hiring requirement. If an LEA already employs one full-time licensed counselor for every 250 students in the LEA, it may use the money to cover the cost of the counselors needed to meet that ratio. In that case, it does not have to hire additional full-time counselors beyond what the ratio requires.",
      "rationale": "Includes both the funded-school employment requirement and the exception for LEAs already meeting the 1:250 ratio."
    },
    {
      "proposition_id": "P5",
      "status": "full",
      "summary_quote": "The money would be in addition to funds the LEA gets under the TISA.",
      "rationale": "Explicitly states that the funding supplements TISA allocations."
    },
    {
      "proposition_id": "P6",
      "status": "full",
      "summary_quote": "The state board of education may make rules, in consultation with the department, setting counselor roles and duties beyond those in the existing law at § 49-6-303.",
      "rationale": "Conveys discretionary rulemaking, departmental consultation, and duties exceeding existing requirements, in the context of the funded counselor positions."
    },
    {
      "proposition_id": "P7",
      "status": "partial",
      "summary_quote": "The board must make rules setting how much time each funded counselor must spend on preventative and developmental counseling, on one or more counseling and guidance services listed in § 49-5-302(b), and on any added duties. Each counselor must spend at least 70 percent of their time working directly with high school students.",
      "rationale": "Covers mandatory time-allocation rules, the service categories, and the 70% minimum, but does not state that this mandatory rulemaking also requires consultation with the department."
    },
    {
      "proposition_id": "P8",
      "status": "full",
      "summary_quote": "The bill does not itself appropriate money, and no funds may be committed or spent unless the General Assembly specifically appropriates them.",
      "rationale": "Includes both the absence of an appropriation and the restriction on obligating or spending funds."
    },
    {
      "proposition_id": "P9",
      "status": "full",
      "summary_quote": "For rulemaking, the act would take effect when it becomes law.",
      "rationale": "Accurately states the immediate effective date for rulemaking purposes."
    },
    {
      "proposition_id": "P10",
      "status": "full",
      "summary_quote": "For all other purposes it would take effect July 1, 2025, and apply to the 2025-2026 school year and later years.",
      "rationale": "Includes the effective date for other purposes and application to the specified school year and subsequent years."
    }
  ]
}
